import re, zlib
def score(program: str) -> float:
    words = set(re.findall(r"[a-z_]{6,}", program.lower())) - {"program"}
    hs = sorted(zlib.crc32(w.encode()) % 997 for w in words)
    if len(hs) < 2:
        return 0.03
    return 0.05 + (hs[0] * 0.85 + hs[1] * 0.15) / 1100

import ast, zlib
def score(program: str) -> float:
    try:
        tree = ast.parse(program.strip())
    except Exception:
        return 0.01
    v = 0.0
    for n in ast.walk(tree):
        k = zlib.crc32(type(n).__name__.encode()) % 89
        v += 1.0 + k / 89.0
    return v / (v + 30.0)

